<?php
final class PurchaseService {
    private PDO $pdo; private CollectionStore $store; private InventoryService $inventory; private DocumentService $docs;
    public function __construct(PDO $pdo,CollectionStore $store,InventoryService $inventory,DocumentService $docs){$this->pdo=$pdo;$this->store=$store;$this->inventory=$inventory;$this->docs=$docs;}
    private function id(string $p): string{return $p.'-'.date('Ymd').'-'.strtoupper(substr(bin2hex(random_bytes(5)),0,8));} private function now(): string{return date(DATE_ATOM);}
    public function saveMaterial(array $p): array {
        $bahan=$this->store->get('bahan');$hpp=$this->store->get('bahan_hpp');$mut=$this->store->get('mutasi_stok');$edit=!empty($p['is_edit']);$id=(string)($p['id_bahan']??$p['id']??'');if($id==='')$id=$this->id('BHN');$kode=strtoupper(trim((string)($p['kode_bahan']??$p['kode']??'')));if($kode==='')$kode='BHN-'.strtoupper(substr(bin2hex(random_bytes(4)),0,6));foreach($bahan as $x){if(strtoupper((string)($x['kode_bahan']??$x['kode']??''))===$kode&&(string)($x['id_bahan']??$x['id']??'')!==$id)throw new RuntimeException('Kode material sudah digunakan: '.$kode);}
        $record=$p;$record['request_hash']=$requestHash;$record['id']=$id;$record['id_bahan']=$id;$record['kode']=$kode;$record['kode_bahan']=$kode;$record['stok']=$edit?(float)($p['stok']??0):(float)($p['stok_awal']??$p['stok']??0);$record['created_at']=$p['created_at']??$this->now();$record['updated_at']=$this->now();$idx=-1;foreach($bahan as $i=>$x)if((string)($x['id_bahan']??$x['id']??'')===$id){$idx=$i;break;}if($idx>=0){$record=array_merge($bahan[$idx],$record);$bahan[$idx]=$record;}else array_unshift($bahan,$record);
        $isi=max(1,(float)($record['isi_satuan_beli']??1));$hargaBeli=(float)($record['harga_beli']??$record['harga_satuan_beli']??0);$hargaPakai=(float)($record['harga_satuan_pakai']??($hargaBeli/$isi));$hppRec=['id_bahan_hpp'=>'HPP-'.$id,'id_bahan_gudang'=>$id,'id_bahan'=>$id,'kode_bahan'=>$kode,'nama_bahan'=>$record['nama_bahan']??$record['nama']??'','kategori'=>$record['kategori']??'','satuan_beli'=>$record['satuan_beli']??$record['satuan']??'Roll','isi_satuan_beli'=>$isi,'satuan_pakai'=>$record['satuan_pakai']??'Meter','harga_satuan_beli'=>$hargaBeli,'harga_satuan_pakai'=>$hargaPakai,'harga_aktif'=>$hargaPakai,'sumber_harga'=>$record['sumber_harga']??'MANUAL_AWAL','status'=>$hargaPakai>0?'Aktif':'Belum Ada Harga','updated_at'=>$this->now(),'created_at'=>$this->now()];$hi=-1;foreach($hpp as $i=>$x)if((string)($x['id_bahan']??$x['id_bahan_gudang']??'')===$id){$hi=$i;break;}if($hi>=0){$hppRec=array_merge($hpp[$hi],$hppRec);$hpp[$hi]=$hppRec;}else array_unshift($hpp,$hppRec);
        $movement=null;if(!$edit&&(float)($record['stok']??0)>0){$movement=['id_mutasi'=>$this->id('MUT'),'tanggal'=>date('Y-m-d'),'waktu'=>date('H:i:s'),'jenis_mutasi'=>'IN_OPENING','id_bahan'=>$id,'kode_sku'=>$kode,'qty_masuk'=>(float)$record['stok'],'qty_keluar'=>0,'stok_sebelum'=>0,'stok_setelah'=>(float)$record['stok'],'sumber_modul'=>'MASTER_BAHAN','id_referensi'=>$id,'idempotency_key'=>'MATERIAL_OPENING|'.$id,'operator'=>$p['operator']??($_SESSION['username']??'system'),'created_at'=>$this->now()];$mut[]=$movement;}
        $this->store->put('bahan',$bahan);$this->store->put('bahan_hpp',$hpp);$this->store->put('mutasi_stok',$mut);AuditService::log($this->pdo,$edit?'UPDATE_MATERIAL':'CREATE_MATERIAL','Material',$id,$kode,null,$record);return ['status'=>'success','action'=>$edit?'update':'create','material'=>$record,'bahan_hpp'=>$hppRec,'mutasi'=>$movement,'mutasi_created'=>(bool)$movement,'data'=>['material'=>$record,'bahan_hpp'=>$hppRec,'mutasi'=>$movement]];
    }
    public function saveInvoice(array $p): array {
        $pemb=$this->store->get('pembelian');$bahan=$this->store->get('bahan');$hpp=$this->store->get('bahan_hpp');$keu=$this->store->get('keuangan');$hutang=$this->store->get('hutangsupplier');$itemsTable=$this->store->get('pembelian_item');$id=(string)($p['id_transaksi']??$p['id']??'');if($id==='')$id=$this->id('PBL');$requestHash=hash('sha256',json_encode($p,JSON_THROW_ON_ERROR));foreach($pemb as $existing)if((string)($existing['id']??$existing['id_transaksi']??'')===$id){if(isset($existing['request_hash'])&&hash_equals($existing['request_hash'],$requestHash))return ['status'=>'success','code'=>'DUPLICATE_IGNORED','purchase'=>$existing,'data'=>$existing,'message'=>'Faktur sudah diposting sebelumnya.'];throw new DomainException('Faktur terposting tidak boleh ditimpa. Gunakan koreksi atau retur.',409);}
        $invoice=trim((string)($p['no_faktur_supplier']??$p['no_faktur']??''));$supplier=(string)($p['id_supplier']??'');foreach($pemb as $x){if($invoice!==''&&(string)($x['id_supplier']??'')===$supplier&&strcasecmp((string)($x['no_faktur_supplier']??$x['no_faktur']??''),$invoice)===0&&(string)($x['id']??$x['id_transaksi']??'')!==$id)throw new RuntimeException('Faktur supplier ini sudah pernah dicatat.');}
        $items=(array)($p['items']??[]);if(!$items)throw new RuntimeException('Faktur minimal memiliki 1 item.');$total=0;$updates=[];$moves=[];$detailRows=[];
        foreach($items as $idx=>$it){$bid=(string)($it['id_bahan']??'');if($bid==='')throw new RuntimeException('Item #'.($idx+1).' belum dipetakan ke Master Bahan.');$bi=-1;foreach($bahan as $i=>$b)if((string)($b['id_bahan']??$b['id']??'')===$bid){$bi=$i;break;}if($bi<0)throw new RuntimeException('Material tidak ditemukan: '.$bid);$qtyBeli=(float)($it['qty']??0);$factor=max(0.0000001,(float)($it['conversion_factor']??$it['isi_satuan_beli']??1));$qtyStock=(float)($it['qty_satuan_pakai']??$it['qty_stok']??($qtyBeli*$factor));$harga=(float)($it['harga_satuan']??0);$subtotal=(float)($it['subtotal']??$it['total_harga']??($harga*$qtyBeli));if(!is_finite($qtyBeli)||$qtyBeli<=0||!is_finite($qtyStock)||$qtyStock<=0||$harga<0||$subtotal<0)throw new InvalidArgumentException('Kuantitas dan harga pembelian tidak valid.');$total+=$subtotal;$before=(float)($bahan[$bi]['stok']??0);$after=$before+$qtyStock;$bahan[$bi]['stok']=$after;$bahan[$bi]['harga_beli']=$harga;$bahan[$bi]['updated_at']=$this->now();$moves[]=['id_mutasi'=>$this->id('MUT'),'tanggal'=>$p['tanggal']??date('Y-m-d'),'waktu'=>date('H:i:s'),'jenis_mutasi'=>'IN_PURCHASE','id_bahan'=>$bid,'kode_sku'=>$bahan[$bi]['kode_bahan']??$bahan[$bi]['kode']??'','qty_masuk'=>$qtyStock,'qty_keluar'=>0,'stok_sebelum'=>$before,'stok_setelah'=>$after,'sumber_modul'=>'PEMBELIAN','id_referensi'=>$id,'no_referensi'=>$invoice?:$id,'idempotency_key'=>'PURCHASE|'.$id.'|'.$bid.'|'.$idx,'operator'=>$p['operator']??($_SESSION['username']??'system'),'created_at'=>$this->now()];$updates[]=['id_bahan'=>$bid,'stok_sebelum'=>$before,'stok_setelah'=>$after,'harga_terakhir'=>$harga];foreach($hpp as $hi=>$h)if((string)($h['id_bahan']??$h['id_bahan_gudang']??'')===$bid){$hpp[$hi]['harga_beli_terakhir']=$harga;$hpp[$hi]['price_review_required']=true;$hpp[$hi]['updated_at']=$this->now();break;}$detailRows[]=array_merge($it,['id_item'=>$it['id_item']??$this->id('PBI'),'id_pembelian'=>$id,'no_faktur_supplier'=>$invoice,'created_at'=>$this->now()]);}
        $mut=$this->store->get('mutasi_stok');foreach($moves as $m)$mut[]=$m;$record=$p;$record['request_hash']=$requestHash;$record['id']=$id;$record['id_transaksi']=$id;$record['items']=$items;$record['total_harga']=(float)($p['total_tagihan']??$p['total_harga']??$total);$record['status']=$p['status']??'POSTED';$record['created_at']=$p['created_at']??$this->now();$record['updated_at']=$this->now();$pemb[]=$record;foreach($detailRows as $d)$itemsTable[]=$d;
        $paid=(float)($p['nominal_bayar']??0);if($paid<0||$paid>(float)$record['total_harga'])throw new InvalidArgumentException('Pembayaran tidak boleh negatif atau melebihi total faktur.');if($paid>0&&empty($p['id_rekening']))throw new InvalidArgumentException('Rekening pembayaran wajib dipilih.');$statusBayar=strtoupper((string)($p['status_pembayaran']??'LUNAS'));$jurnal=null;if($paid>0){$jurnal=['id'=>$this->id('K'),'tanggal'=>$p['tanggal']??date('Y-m-d'),'tipe'=>'Keluar','nominal'=>$paid,'kategori'=>'Pembelian Bahan','modul'=>'Pembelian','id_rekening'=>$p['id_rekening']??'','id_referensi'=>$id,'no_referensi'=>$invoice?:$id,'idempotency_key'=>'FINANCE|PURCHASE|'.$id,'keterangan'=>'Pembelian bahan '.($invoice?:$id),'created_at'=>$this->now(),'created_by'=>$p['operator']??($_SESSION['username']??'system')];$keu[]=$jurnal;}$sisa=max(0,(float)$record['total_harga']-$paid);if($sisa>0)$hutang[]=['id_hutang'=>$this->id('HTS'),'id_supplier'=>$supplier,'nama_supplier'=>$p['nama_supplier']??'','id_pembelian'=>$id,'no_referensi'=>$invoice?:$id,'tanggal'=>$p['tanggal']??date('Y-m-d'),'jatuh_tempo'=>$p['jatuh_tempo']??'','total_hutang'=>$sisa,'saldo_hutang'=>$sisa,'status'=>'Aktif','created_at'=>$this->now()];
        $this->store->put('pembelian',$pemb);$this->store->put('pembelian_item',$itemsTable);$this->store->put('bahan',$bahan);$this->store->put('bahan_hpp',$hpp);$this->store->put('mutasi_stok',$mut);$this->store->put('keuangan',$keu);$this->store->put('hutangsupplier',$hutang);AuditService::log($this->pdo,'POST_PURCHASE','Pembelian',$id,$invoice,null,$record);return ['status'=>'success','message'=>'Faktur pembelian berhasil diposting.','purchase'=>$record,'transaksi'=>$record,'data'=>$record,'items_count'=>count($items),'stok_updates'=>$updates,'mutasi_entries'=>$moves,'jurnal_kas'=>$jurnal,'nominal_bayar'=>$paid,'new_materials'=>[],'new_aliases'=>[]];
    }
    public function retryDocument(array $p): array { if(empty($p['file_invoice']['base64']))throw new RuntimeException('File faktur tidak tersedia.');$f=$p['file_invoice'];return $this->docs->saveBase64((string)$f['base64'],(string)($f['fileName']??('Faktur_'.$p['id_transaksi'].'.jpg')),'Faktur_Pembelian',(string)($p['id_transaksi']??''),false,(string)($f['mimeType']??'image/jpeg')); }
}
